"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[4348],{88833:e=>{e.exports=JSON.parse('{"functions":[{"name":"childrenOf","desc":"The children of an instance, memoized.\\n\\nThis must be read *before* the children are detached, and it is what makes a\\nsecond show cycle work: the hierarchy is unchanged between hide and show, so\\nthe recorded list stays correct even though the instance is momentarily\\nchildless.\\n\\nKeyed weakly, so an instance the game destroys is not pinned in memory by its\\nown cache entry.","params":[{"name":"instance","desc":"","lua_type":"Instance"}],"returns":[{"desc":"","lua_type":"{ Instance }"}],"function_type":"static","private":true,"source":{"line":71,"path":"src/main/shared/utils/slowParent.luau"}},{"name":"enqueue","desc":"Queues a hierarchy to be streamed into `destination`.\\n\\nThe root is parented immediately, but it is emptied first, so this call\\nadmits exactly one instance no matter how large the subtree is.","params":[{"name":"subject","desc":"Detached hierarchy to admit.","lua_type":"Instance"},{"name":"destination","desc":"Where the root belongs.","lua_type":"Instance"},{"name":"onComplete","desc":"Called once streaming finishes.","lua_type":"(Instance) -> ()"}],"returns":[{"desc":"The same subject, now parented but not yet filled.","lua_type":"Instance"}],"function_type":"static","source":{"line":92,"path":"src/main/shared/utils/slowParent.luau"}},{"name":"processNext","desc":"Admits nodes until the deadline passes or the per-call cap is reached,\\noldest job first.\\n\\nThe node cap exists because time is not the only cost here: a burst of parent\\nwrites inside one frame is charged by the engine on the following frame\\nregardless of how quickly the writes themselves returned.\\n\\nAlways admits at least one node per call, so an over-budget frame still makes\\nprogress rather than leaving hierarchies half-visible forever.","params":[{"name":"deadline","desc":"`os.clock()` value to stop at.","lua_type":"number"},{"name":"maxNodes","desc":"Hard cap on nodes admitted this call. Defaults to 50.","lua_type":"number?"}],"returns":[{"desc":"Nodes admitted.","lua_type":"number"}],"function_type":"static","source":{"line":130,"path":"src/main/shared/utils/slowParent.luau"}},{"name":"clear","desc":"Drops every queued job. Roots already parented stay where they are, partially\\nfilled, so the caller must destroy anything it does not want left behind.","params":[],"returns":[],"function_type":"static","source":{"line":184,"path":"src/main/shared/utils/slowParent.luau"}}],"properties":[],"types":[{"name":"Chunk","desc":"One parent and the children still owed to it.","fields":[{"name":"sources","lua_type":"{ Instance }","desc":"Nodes still to admit."},{"name":"parent","lua_type":"Instance","desc":"Where they belong."},{"name":"head","lua_type":"number","desc":"Next source index, 1-based."}],"source":{"line":32,"path":"src/main/shared/utils/slowParent.luau"}},{"name":"Job","desc":"One hierarchy part-way into the world.","fields":[{"name":"root","lua_type":"Instance","desc":"The hierarchy being streamed in."},{"name":"chunks","lua_type":"{ Chunk }","desc":"Outstanding work."},{"name":"chunkHead","lua_type":"number","desc":"Next chunk index, 1-based."},{"name":"onComplete","lua_type":"(Instance) -> ()","desc":"Called once every descendant is back in place."}],"source":{"line":44,"path":"src/main/shared/utils/slowParent.luau"}}],"name":"slowParent","desc":"Streams a detached hierarchy into the world one node at a time.\\n\\nParenting a large subtree in one assignment makes the engine register every\\ndescendant at once \u2014 streaming, physics and replication all bill for it in\\nthe same frame. This walks the tree instead: before a node is dropped into\\nthe live world its own children are detached, so each individual parent write\\nonly ever admits one instance.\\n\\nThe mirror of [slowClone]: that one builds a hierarchy out of sight, this one\\nadmits it to the world gradually.\\n\\nAdapted from the `feat/better-maze-generation` prototype, with two fixes \u2014\\nthe per-call node cap was being compared against the microsecond budget\\nrather than its own argument, so it never applied; and the budget is now the\\npipeline\'s shared frame deadline.","tags":["shared-util"],"source":{"line":22,"path":"src/main/shared/utils/slowParent.luau"}}')}}]);